validator:
function validate(input) {
  const [{ Customers = [], Orders = [] }] = input;
  const customers = new Set(), orders = new Set();
  for (const [id] of Customers) {
    if (id === null) return 'Every customer needs an id.';
    if (customers.has(id)) return `Customer id ${id} appears twice.`;
    customers.add(id);
  }
  for (const [id, customerId] of Orders) {
    if (id === null) return 'Every order needs an id.';
    if (orders.has(id)) return `Order id ${id} appears twice.`;
    if (!customers.has(customerId)) return `Order ${id} names customer ${customerId}, who is not in Customers.`;
    orders.add(id);
  }
  return null;
}

generator:
function generate(rand, size) {
  const names = ['Joe', 'Henry', 'Sam', 'Max', 'Ana', 'Ravi'];
  const small = size === 'small';
  const Customers = [], Orders = [];
  const customerCount = small ? Math.floor(rand() * 7) : 1000;
  const ids = [];
  for (let i = 0; i < customerCount; i++) {
    // Gaps in the ids keep order ids and customer ids from lining up by accident.
    const id = small ? i * 2 + 1 + Math.floor(rand() * 2) : i + 1;
    ids.push(id);
    Customers.push([id, names[Math.floor(rand() * names.length)]]);
  }
  if (ids.length > 0) {
    // Orders favour a few customers, so some customers have several orders and others none.
    const buyers = ids.filter(() => rand() < 0.6);
    if (buyers.length > 0) {
      const orderCount = small ? Math.floor(rand() * 9) : 2000;
      for (let id = 1; id <= orderCount; id++) Orders.push([id, buyers[Math.floor(rand() * buyers.length)]]);
    }
  }
  return [{ Customers, Orders }];
}
